public class DatabaseConnectionPool {
    // volatile ensures changes to instance are immediately visible to other threads
    private static volatile DatabaseConnectionPool instance;

    // private constructor prevents instantiation from outside
    private DatabaseConnectionPool() {
        // init pool
    }

    public static DatabaseConnectionPool getInstance() {
        if (instance == null) { // First check (no locking)
            synchronized (DatabaseConnectionPool.class) {
                if (instance == null) { // Second check (with locking)
                    instance = new DatabaseConnectionPool();
                }
            }
        }
        return instance;
    }
}

class SingletonMeta(type):
    _instances = {}
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            # create the instance and save it
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
    def __init__(self):
        print("Initializing connection...")

db1 = DatabaseConnection()
db2 = DatabaseConnection()
print(db1 is db2)  # Output: True (only initialized once)

// --- TypeScript Manual Factory ---
interface Notification { send(msg: string): void; }

class EmailNotification implements Notification {
    send(msg: string) { console.log(`Email sent: ${msg}`); }
}
class PushNotification implements Notification {
    send(msg: string) { console.log(`Push sent: ${msg}`); }
}

class NotificationFactory {
    static create(type: 'EMAIL' | 'PUSH'): Notification {
        switch(type) {
            case 'EMAIL': return new EmailNotification();
            case 'PUSH': return new PushNotification();
            default: throw new Error('Unknown type');
        }
    }
}

// --- Spring Boot Factory via Dependency Injection ---
// Define beans for each type, then inject a Map<String, Notification>
// This adheres perfectly to Open/Closed Principle!
@Service
public class NotificationService {
    // Spring automatically populates this map where keys are component names
    private final Map<String, Notification> notificationStrategies;

    @Autowired
    public NotificationService(Map<String, Notification> strategies) {
        this.notificationStrategies = strategies;
    }

    public void send(String type, String message) {
        Notification notifier = notificationStrategies.get(type.toLowerCase() + "Notification");
        if (notifier == null) throw new IllegalArgumentException("Invalid type");
        notifier.send(message);
    }
}

