interface Observer { update(price: number): void; }

class StockTicker {
    private observers: Observer[] = [];
    private price: number = 0;

    subscribe(obs: Observer) { this.observers.push(obs); }

    setPrice(newPrice: number) {
        this.price = newPrice;
        this.notify();
    }

    private notify() {
        for (const obs of this.observers) {
            obs.update(this.price);
        }
    }
}

class MobileAppDashboard implements Observer {
    update(price: number) { console.log(`Mobile UI updated: $${price}`); }
}

// VALUE OBJECT: Immutable, no ID, defined by properties
record Money(BigDecimal amount, String currency) {
    public Money add(Money other) {
        if (!this.currency.equals(other.currency)) throw new IllegalArgumentException("Currency mismatch");
        return new Money(this.amount.add(other.amount), this.currency);
    }
}

// ENTITY (AGGREGATE ROOT): Mutable, has ID, enforces invariants
class Order {
    private final String orderId;
    private OrderStatus status;
    private Money totalAmount; // Using Value Object

    public Order(String id) {
        this.orderId = id;
        this.status = OrderStatus.CREATED;
        this.totalAmount = new Money(BigDecimal.ZERO, "USD");
    }

    // Business logic centralized here, not in a "Service" class
    public void addItem(OrderItem item) {
        if (status != OrderStatus.CREATED) {
            throw new IllegalStateException("Cannot modify paid order");
        }
        this.totalAmount = this.totalAmount.add(item.getPrice());
    }
}

public class Theater {
    private final Map<String, Seat> seats = new HashMap<>();
    private final Lock globalLock = new ReentrantLock();

    // BAD approach: synchronized method locks the whole Theater. Only 1 booking globally at a time!
    // public synchronized boolean bookSeatBad(String seatId) { ... }

    // GOOD approach: Fine-grained locking. Lock only the specific seat.
    public boolean bookSeat(String seatId, User user) {
        Seat seat = seats.get(seatId);
        if (seat == null) throw new InvalidSeatException(seatId);

        // Try to lock the specific seat. If another thread holds the lock, tryLock returns false immediately.
        if (seat.getLock().tryLock()) {
            try {
                if (seat.isAvailable()) {
                    seat.book(user);
                    return true;
                }
                return false; // Already booked
            } finally {
                seat.getLock().unlock(); // ALWAYS unlock in finally block
            }
        }
        return false; // Could not acquire lock, meaning someone else is booking it right now
    }
}

